mapper.select:
SELECT o.*, f.firmware_name, f.version as firmware_version FROM ota_task o LEFT JOIN firmware f ON o.firmware_id = f.id WHERE o.deleted = 0
AND o.task_code LIKE CONCAT('%', #{dto.taskCode}, '%')
AND o.task_name LIKE CONCAT('%', #{dto.taskName}, '%')
AND o.task_type = #{dto.taskType}
AND o.task_status = #{dto.taskStatus}
ORDER BY o.create_time DESC
